import { randomBytes } from 'node:crypto';
import { constants, createReadStream, createWriteStream, promises as fs } from 'node:fs';
import * as path from 'node:path';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { ByteRange, StorageProvider, StoredObjectInfo } from './storage.provider';

// Keys are generated by StorageService, never by clients; this is a second line of defence.
const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9/_.-]*$/;

/**
 * Stores objects as plain files under STORAGE_ROOT on this server's disk (e.g. an EBS
 * volume on EC2). Writes go to a temp file in the same directory and are renamed into
 * place, so a crash never leaves a half-written object under the real key.
 */
export class LocalDiskStorageProvider extends StorageProvider {
  readonly name = 'local';

  constructor(private readonly root: string) {
    super();
  }

  override localPath(key: string): string {
    if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error(`Invalid storage key: ${key}`);
    const full = path.join(this.root, ...key.split('/'));
    if (!full.startsWith(this.root + path.sep)) throw new Error(`Invalid storage key: ${key}`);
    return full;
  }

  async put(key: string, body: Readable): Promise<{ size: number }> {
    const target = this.localPath(key);
    await fs.mkdir(path.dirname(target), { recursive: true });
    const tmp = `${target}.${randomBytes(6).toString('hex')}.part`;
    try {
      await pipeline(body, createWriteStream(tmp, { flags: 'wx' }));
      await fs.rename(tmp, target);
    } catch (err) {
      await fs.rm(tmp, { force: true }).catch(() => undefined);
      throw err;
    }
    const { size } = await fs.stat(target);
    return { size };
  }

  async get(key: string, range?: ByteRange): Promise<Readable> {
    const file = this.localPath(key);
    // Open first so a missing file rejects here instead of erroring mid-response.
    const handle = await fs.open(file, 'r');
    return createReadStream('', { fd: handle.fd, autoClose: true, start: range?.start, end: range?.end });
  }

  async stat(key: string): Promise<StoredObjectInfo | null> {
    try {
      const s = await fs.stat(this.localPath(key));
      return s.isFile() ? { size: s.size, modifiedAt: s.mtime } : null;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  }

  async exists(key: string): Promise<boolean> {
    return (await this.stat(key)) !== null;
  }

  async delete(key: string): Promise<void> {
    await fs.rm(this.localPath(key), { force: true });
  }

  async deletePrefix(prefix: string): Promise<void> {
    await fs.rm(this.localPath(prefix.replace(/\/+$/, '')), { recursive: true, force: true });
  }

  async copy(sourceKey: string, destinationKey: string): Promise<void> {
    const target = this.localPath(destinationKey);
    await fs.mkdir(path.dirname(target), { recursive: true });
    const tmp = `${target}.${randomBytes(6).toString('hex')}.part`;
    try {
      // Copy-on-write clone where the filesystem supports it (XFS/btrfs), plain copy otherwise.
      await fs.copyFile(this.localPath(sourceKey), tmp, constants.COPYFILE_FICLONE);
      await fs.rename(tmp, target);
    } catch (err) {
      await fs.rm(tmp, { force: true }).catch(() => undefined);
      throw err;
    }
  }

  async healthCheck(): Promise<boolean> {
    try {
      await fs.mkdir(this.root, { recursive: true });
      const probe = path.join(this.root, `.health-${process.pid}`);
      await fs.writeFile(probe, 'ok');
      await fs.rm(probe, { force: true });
      return true;
    } catch {
      return false;
    }
  }
}
